case "new-supplier":
  openSupplierModal();
  return;
case "edit-supplier": {
  const s = getState().suppliers.find((x) => x.id === id);
  if (s) openSupplierModal(s);
  return;
}
case "delete-supplier": {
  const s = getState().suppliers.find((x) => x.id === id);
  if (!s) return;
  const n = invoicesOf(s.id).length;
  const ok = await confirmDialog({
    title: "Borrar el proveedor",
    message: n
      ? `Se borrará «${s.name}» y sus ${n} facturas. Esto no se puede deshacer.`
      : `Se borrará «${s.name}». No tiene facturas.`,
    confirm: "Sí, borrarlo",
    danger: true,
  });
  if (!ok) return;
  deleteSupplier(id);
  toast("Proveedor borrado.");
  render();
  return;
}
case "filter-supplier":
  ui.filters.supplier = id;
  ui.filters.status = "all";
  location.hash = "#/compras";
  render();
  return;
case "import-files":
  document.getElementById("filePicker").click();
  return;
case "import-camera":
  importFromCamera();
  return;
case "export-sqlite":
  exportSqlite();
  return;
case "paste-text":
  openPasteModal();
  return;
case "import-email":
  pickEmails();
  return;
case "paste-mail":
  openMailPasteModal();
  return;
case "use-mail":
  useMail(id);
  return;
case "delete-mail": {
  const ok = await confirmDialog({
    title: "Borrar el correo",
    message: "Se quita de la lista. Las facturas que ya hayas guardado desde él no se tocan.",
    confirm: "Sí, borrar",
    danger: true,
  });
  if (!ok) return;
  deleteMessage(id);
  toast("Correo borrado.");
  render();
  return;
}
